#!/bin/bash
# Runs once, as root, before the agent starts: Harbor's [environment.healthcheck] unpacks this folder into
# /var/lib/mimo and runs it. Generated by mimo_harbor; see its README for how each step maps to Xiaomi's harness.
M=/var/lib/mimo
[ -f "$M/ready" ] && exit 0
chmod 700 "$M"
fail() { echo "setup: $*" >&2; exit 1; }
# the answer-leak blocklist (mimoagent), applied to /etc/hosts by the agent right after it installs
write_blocklist() { cp "$M/files/blocklist" "$M/blocklist"; }

# Terminal-Bench rows (in the General domain): the Harbor convention itself. Scrub test leftovers from the image and
# remember what was in the workspace, so harness residue can be told apart from the agent's work at grading time.
rm -rf /tests
find /logs/verifier -mindepth 1 -delete 2>/dev/null || true
ls -A /app 2>/dev/null > "$M/before" || true

# env-prefetch-network@1: grading imports this module; fetch while the network is open.
python3 -m pip install stevedore > "$M/env-prefetch-network.log" 2>&1 || fail "env-prefetch-network@1 cannot install stevedore"
# terminal-guard-extend@1: snapshot interpreter/plugin hooks before the agent starts.
_terminal_guard_snapshot="$M/terminal-guard-snapshot.json"
python3 -S - "$_terminal_guard_snapshot" <<'TERMINAL_GUARD_SNAPSHOT_EOF' || fail "terminal-guard-extend@1 cannot snapshot interpreter hooks"
import hashlib
import json
import os
import shutil
import sys
import sysconfig
from typing import Any

def guard_site_dirs() -> list[str]:
    """Site directories to police, without importing the ``site`` module.

    Runs under ``python3 -S`` (no ``site`` import, so a planted
    ``sitecustomize`` cannot execute inside the guard/snapshot process).
    """
    import os
    import sys

    version = f"python{sys.version_info[0]}.{sys.version_info[1]}"
    found: list[str] = []
    for prefix in (sys.prefix, sys.exec_prefix):
        for layout in ("site-packages", "dist-packages"):
            candidate = os.path.join(prefix, "lib", version, layout)
            if os.path.isdir(candidate) and candidate not in found:
                found.append(candidate)
    return found

def collect_snapshot(site_dirs: list[str]) -> dict[str, Any]:
    """Snapshot hook files and pytest11 plugins under ``site_dirs``.

    Returns a JSON-serializable doc with absolute-path keys. Hook files are
    ``sitecustomize.py`` / ``usercustomize.py`` / ``*.pth`` with sha256.
    Plugins map entry-point name to value, providing dist name/version and
    the sha256 of the plugin module files the value resolves to.
    """
    import hashlib
    import os

    hooks: dict[str, str] = {}
    for site_dir in site_dirs:
        try:
            names = sorted(os.listdir(site_dir))
        except OSError:
            continue
        for name in names:
            path = os.path.join(site_dir, name)
            if not os.path.isfile(path):
                continue
            if name in ("sitecustomize.py", "usercustomize.py") or name.endswith(".pth"):
                with open(path, "rb") as handle:
                    hooks[path] = "sha256:" + hashlib.sha256(handle.read()).hexdigest()
    plugins: dict[str, dict[str, Any]] = {}
    for site_dir in site_dirs:
        try:
            names = sorted(os.listdir(site_dir))
        except OSError:
            continue
        for name in names:
            if not (name.endswith(".dist-info") or name.endswith(".egg-info")):
                continue
            dist_dir = os.path.join(site_dir, name)
            entry_points = _read_entry_points(dist_dir)
            if "pytest11" not in entry_points:
                continue
            version = _read_dist_version(dist_dir)
            for ep_name, value in sorted(entry_points["pytest11"].items()):
                files: dict[str, str] = {}
                for module_file in _plugin_module_files(site_dir, value):
                    with open(module_file, "rb") as handle:
                        files[module_file] = "sha256:" + hashlib.sha256(handle.read()).hexdigest()
                plugins[ep_name] = {
                    "value": value,
                    "dist": name,
                    "version": version,
                    "files": files,
                }
    return {"site_dirs": list(site_dirs), "hooks": hooks, "plugins": plugins}

def _read_entry_points(dist_dir: str) -> dict[str, dict[str, str]]:
    """Parse ``entry_points.txt`` of one installed distribution."""
    import os

    path = os.path.join(dist_dir, "entry_points.txt")
    groups: dict[str, dict[str, str]] = {}
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except OSError:
        return groups
    group = ""
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            group = line[1:-1].strip()
            groups.setdefault(group, {})
        elif "=" in line and group:
            ep_name, _, value = line.partition("=")
            ep_name = ep_name.strip()
            value = value.split(";")[0].strip()
            if ep_name and value:
                groups[group][ep_name] = value
    return groups

def _read_dist_version(dist_dir: str) -> str:
    """Read the installed version from METADATA / PKG-INFO."""
    import os

    for filename in ("METADATA", "PKG-INFO"):
        try:
            with open(os.path.join(dist_dir, filename), encoding="utf-8") as handle:
                text = handle.read()
        except OSError:
            continue
        for line in text.splitlines():
            if line.startswith("Version:"):
                return line.partition(":")[2].strip()
    return ""

def _plugin_module_files(site_dir: str, value: str) -> list[str]:
    """Files an entry-point value resolves to (``mod`` or ``mod:attr``)."""
    import os

    dotted = value.split(":")[0].strip()
    if not dotted or not all(part.isidentifier() for part in dotted.split(".")):
        return []
    parts = dotted.split(".")
    candidates = [os.path.join(site_dir, *parts[:-1], parts[-1] + ".py")]
    candidates.append(os.path.join(site_dir, *parts, "__init__.py"))
    for depth in range(1, len(parts)):
        candidates.append(os.path.join(site_dir, *parts[:depth], "__init__.py"))
    seen: list[str] = []
    for candidate in candidates:
        if os.path.isfile(candidate) and candidate not in seen:
            seen.append(candidate)
    return seen

def check_snapshot(
    snapshot: dict[str, Any], site_dirs: list[str], quarantine_dir: str
) -> tuple[list[str], str | None]:
    """Enforce a snapshot: quarantine plants, fail closed on anchor tamper.

    Returns ``(quarantined, reason)``: absolute paths moved aside, and a
    reject reason (``None`` when grading may continue). Hook files absent
    from the snapshot are quarantined (moved, not deleted). Snapshotted hook
    or plugin files whose bytes changed or vanished are a reject. Newly
    appeared ``pytest11`` entry points are only logged:
    ``PYTEST_DISABLE_PLUGIN_AUTOLOAD=1`` keeps them out of grading.
    """
    import hashlib
    import os
    import shutil

    quarantined: list[str] = []
    expected_hooks = dict(snapshot.get("hooks") or {})
    expected_plugins = dict(snapshot.get("plugins") or {})

    def _quarantine(path: str) -> None:
        os.makedirs(quarantine_dir, exist_ok=True)
        target = os.path.join(quarantine_dir, path.lstrip("/").replace("/", "__"))
        suffix = 0
        while os.path.exists(target if suffix == 0 else f"{target}.{suffix}"):
            suffix += 1
        if suffix:
            target = f"{target}.{suffix}"
        shutil.move(path, target)
        quarantined.append(path)

    current_hooks: set[str] = set()
    for site_dir in site_dirs:
        try:
            names = sorted(os.listdir(site_dir))
        except OSError:
            continue
        for name in names:
            path = os.path.join(site_dir, name)
            if not os.path.isfile(path):
                continue
            if name in ("sitecustomize.py", "usercustomize.py") or name.endswith(".pth"):
                current_hooks.add(path)
    for path in sorted(current_hooks):
        if path not in expected_hooks:
            _quarantine(path)
    for path in sorted(expected_hooks):
        if path in quarantined:
            continue
        if not os.path.isfile(path):
            return quarantined, f"protected_interpreter_hook_deleted:{path}"
        with open(path, "rb") as handle:
            digest = "sha256:" + hashlib.sha256(handle.read()).hexdigest()
        if digest != expected_hooks[path]:
            return quarantined, f"protected_interpreter_hook_mutated:{path}"
    current_plugins = collect_snapshot(site_dirs)["plugins"]
    for ep_name in sorted(current_plugins):
        if ep_name not in expected_plugins:
            os.makedirs(quarantine_dir, exist_ok=True)
            with open(os.path.join(quarantine_dir, "new_pytest_plugins.log"), "a", encoding="utf-8") as handle:
                handle.write(f"unpinned pytest11 entry point (autoload disabled): {ep_name}\n")
    for ep_name in sorted(expected_plugins):
        expected = expected_plugins[ep_name]
        current = current_plugins.get(ep_name)
        if current is None:
            return quarantined, f"protected_pytest_plugin_deleted:{ep_name}"
        if current.get("value") != expected.get("value"):
            return quarantined, f"protected_pytest_plugin_mutated:{ep_name}"
        expected_files = dict(expected.get("files") or {})
        current_files = dict(current.get("files") or {})
        for module_file in sorted(expected_files):
            if current_files.get(module_file) != expected_files[module_file]:
                return quarantined, f"protected_pytest_plugin_mutated:{ep_name}"
    return quarantined, None
_snapshot_out = sys.argv[1]
_snapshot_dirs = guard_site_dirs()
_snapshot_doc = collect_snapshot(_snapshot_dirs)
_snapshot_doc["schema"] = "terminal-guard-snapshot/v1"
with open(_snapshot_out, "w", encoding="utf-8") as _snapshot_handle:
    json.dump(_snapshot_doc, _snapshot_handle, indent=2, sort_keys=True)
    _snapshot_handle.write("\n")
print(f"terminal-guard-extend@1: snapshotted {len(_snapshot_doc['hooks'])} hook(s), "
      f"{len(_snapshot_doc['plugins'])} pytest plugin(s) in {len(_snapshot_dirs)} site dir(s)")
TERMINAL_GUARD_SNAPSHOT_EOF
[ -s "$_terminal_guard_snapshot" ] || fail "terminal-guard-extend@1 snapshot is empty"
touch "$M/ready"
echo "setup done"

#!/usr/bin/env python3
"""TBench in-pod anti-hack guard.

Runs at the very start of ``tests/test.sh``, inside the verifier container,
after the agent's ``/app`` has been copied in.  The RL harness materialises
``tests/`` into the MAIN container only after the agent exits, so the agent
cannot see or tamper with this file — which makes it the right place to reject
workspace pollution the agent planted during the episode.

Detection (any hit -> write reward=0 and exit non-zero):

1. **Planted interpreter hooks.**  ``conftest.py`` / ``sitecustomize.py`` /
   ``usercustomize.py`` / ``*.pth`` / ``pytest.ini`` / ``.coveragerc`` /
   ``tox.ini`` anywhere under ``/app`` whose path is NOT listed in the pristine
   manifest.  Upstream vendor trees that legitimately ship a ``conftest.py``
   are listed in the manifest and are therefore not false positives.
2. **Protected-file mutation.**  Any manifest entry whose sha256 changed while
   its path is outside the declared mutable set.
3. **Protected-file deletion.**  Any non-mutable, non-artifact manifest entry
   that vanished.

The manifest is generated from the pristine ``environment/`` tree and shipped
as ``tests/fixtures/pristine_env_manifest.json``.  A missing manifest degrades to
name-only detection so the guard never blocks an uninstrumented task.
"""

from __future__ import annotations

import hashlib
import json
import os
import sys
from pathlib import Path

SCHEMA = "tbench.pristine_env_manifest.v1"

APP = Path(os.environ.get("TBENCH_APP_ROOT", "/app"))
FIXTURES = Path(os.environ.get("TBENCH_FIXTURES", "/tests/fixtures"))
MANIFEST = FIXTURES / "pristine_env_manifest.json"
REWARD = Path(os.environ.get("TBENCH_REWARD_FILE", "/logs/verifier/reward.txt"))

DANGEROUS_NAMES = {
    "conftest.py",
    "sitecustomize.py",
    "usercustomize.py",
    "pytest.ini",
    ".coveragerc",
    "tox.ini",
    "pyproject.toml",  # only dangerous when planted; upstream copies are in the manifest
}


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def is_dangerous(rel: str) -> bool:
    name = rel.rsplit("/", 1)[-1]
    return name in DANGEROUS_NAMES or name.endswith(".pth")


def load_manifest() -> dict | None:
    if not MANIFEST.is_file():
        return None
    try:
        doc = json.loads(MANIFEST.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if not isinstance(doc, dict) or not isinstance(doc.get("files"), dict):
        return None
    return doc


def reject(reason: str, reward: Path | None = None) -> int:
    target = REWARD if reward is None else reward
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text("0\n", encoding="utf-8")
    except OSError as exc:  # pragma: no cover - reward file is the contract
        print(f"anti_hack_guard: cannot write reward file: {exc}", file=sys.stderr)
        return 2
    print(f"anti_hack_guard: REJECT {reason}", file=sys.stderr)
    return 1


def scan(manifest: dict | None, app: Path | None = None) -> str | None:
    app_root = APP if app is None else app
    files: dict[str, str] = (manifest or {}).get("files") or {}
    mutable_set = {
        entry.lstrip("/")
        for entry in (manifest or {}).get("mutable") or []
        if isinstance(entry, str)
    }
    artifacts = {
        str(entry).removeprefix("/app/").lstrip("/")
        for entry in (manifest or {}).get("artifacts") or []
        if isinstance(entry, str)
    }

    if not app_root.is_dir():
        return None

    for path in sorted(app_root.rglob("*")):
        if not path.is_file() or path.is_symlink():
            continue
        rel = path.relative_to(app_root).as_posix()
        if is_dangerous(rel) and rel not in files:
            return f"planted_interpreter_hook:{rel}"

    if manifest is None:
        return None

    # Deletion detection is only sound when the built image is known to equal
    # the source tree (plain ``COPY . /app``).  A multi-stage or dockerignored
    # build legitimately omits files, and rejecting those would zero out the
    # oracle for a perfectly good task.
    detect_deletion = bool(manifest.get("detect_deletion", True))
    for rel, expected in files.items():
        if rel in mutable_set or rel in artifacts:
            continue
        path = app_root / rel
        if not path.exists():
            if detect_deletion:
                return f"protected_file_deleted:{rel}"
            continue
        if not path.is_file():
            continue
        if sha256(path) != expected:
            return f"protected_file_mutated:{rel}"
    return None


def main(app: Path | None = None, reward: Path | None = None) -> int:
    manifest = load_manifest()
    reason = scan(manifest, app=app)
    if reason:
        return reject(reason, reward=reward)
    extended = run_site_check()
    if extended:
        return reject(extended, reward=reward)
    return 0


